// Source of truth: render/src/main/resources/shaders/. These are the exact
// shaders the Android and desktop clients compile, with #pragma include
// resolved. WebGL 2's shading language is GLSL ES 3.00, which is what they
// were written against, so they need no translation at all.
export const SHADERS = {
  "bloom_blur.frag": "// Separable nine-tap Gaussian, run once per axis at reduced resolution.\nin vec2 v_uv;\nout vec4 fragColor;\n\nuniform sampler2D u_source;\nuniform vec2 u_texelStep;   // (1/width, 0) or (0, 1/height)\n\nvoid main() {\n    const float w0 = 0.227027;\n    const float w1 = 0.194594;\n    const float w2 = 0.121621;\n    const float w3 = 0.054054;\n    const float w4 = 0.016216;\n\n    vec3 sum = texture(u_source, v_uv).rgb * w0;\n    sum += texture(u_source, v_uv + u_texelStep * 1.0).rgb * w1;\n    sum += texture(u_source, v_uv - u_texelStep * 1.0).rgb * w1;\n    sum += texture(u_source, v_uv + u_texelStep * 2.0).rgb * w2;\n    sum += texture(u_source, v_uv - u_texelStep * 2.0).rgb * w2;\n    sum += texture(u_source, v_uv + u_texelStep * 3.0).rgb * w3;\n    sum += texture(u_source, v_uv - u_texelStep * 3.0).rgb * w3;\n    sum += texture(u_source, v_uv + u_texelStep * 4.0).rgb * w4;\n    sum += texture(u_source, v_uv - u_texelStep * 4.0).rgb * w4;\n    fragColor = vec4(sum, 1.0);\n}\n",
  "bloom_threshold.frag": "// Isolates the part of the image above the bloom knee. On water this is almost\n// entirely sun glitter, which is the point: the bloom exists to make the specular\n// track bleed, not to fog the whole frame.\nin vec2 v_uv;\nout vec4 fragColor;\n\nuniform sampler2D u_source;\nuniform float u_threshold;\nuniform float u_softKnee;\nuniform float u_exposure;\n\nvoid main() {\n    // Exposure is applied here, before the threshold. The scene buffer holds\n    // absolute radiance in kcd/m^2, where a plain daylight sky is already around\n    // 9, so thresholding the raw values would treat the entire sky as a highlight\n    // and bloom the whole frame into fog.\n    vec3 c = texture(u_source, v_uv).rgb * u_exposure;\n    float brightness = max(c.r, max(c.g, c.b));\n    float knee = u_threshold * u_softKnee;\n    float soft = clamp(brightness - u_threshold + knee, 0.0, 2.0 * knee);\n    soft = soft * soft / (4.0 * knee + 1e-4);\n    float weight = max(soft, brightness - u_threshold) / max(brightness, 1e-4);\n    fragColor = vec4(c * weight, 1.0);\n}\n",
  "boat.frag": "// Boat shading.\n//\n// Lit by exactly the same sun and sky the water is, through the same analytic\n// model, so the boat cannot end up looking pasted onto the scene - which is the\n// usual giveaway when a hull is lit by its own private light rig.\n\n// Analytic daylight sky, after Preetham, Shirley and Smits (1999).\n//\n// The design brief asks for Hosek-Wilkie with Preetham as the fallback. Preetham\n// is what is implemented, deliberately: Hosek-Wilkie's radiance is driven by a\n// large fitted dataset published by its authors, and that dataset has to be\n// imported from them rather than reproduced from memory. Preetham's coefficients\n// are a small closed-form table in the paper, so they can be written down, read\n// back, and checked. PreethamSkyTest in core verifies this model's behaviour\n// against physical expectations.\n//\n//   F(theta, gamma) = (1 + A e^{B/cos theta}) (1 + C e^{D gamma} + E cos^2 gamma)\n//\n// evaluated for luminance Y and for the chromaticity coordinates x and y, each\n// normalised against the value at the zenith.\n\nconst float SKY_PI = 3.14159265359;\n\nfloat perezF(float cosTheta, float gamma, float a, float b, float c, float d, float e) {\n    float cosGamma = cos(gamma);\n    return (1.0 + a * exp(b / max(cosTheta, 0.01)))\n         * (1.0 + c * exp(d * gamma) + e * cosGamma * cosGamma);\n}\n\nvec3 xyYToLinearSrgb(float x, float y, float bigY) {\n    float safeY = max(y, 1e-4);\n    vec3 xyz = vec3(x * bigY / safeY, bigY, (1.0 - x - y) * bigY / safeY);\n    // XYZ -> linear sRGB (sRGB primaries, D65). Column-major, as GLSL expects.\n    mat3 m = mat3(\n        3.2404542, -0.9692660,  0.0556434,\n       -1.5371385,  1.8760108, -0.2040259,\n       -0.4985314,  0.0415560,  1.0572252);\n    return m * xyz;\n}\n\n// dir and sunDir must be unit vectors with +y up. Returns linear RGB radiance in\n// kcd/m^2; a clear zenith at a 30 degree sun elevation lands around 2.\nvec3 preethamSky(vec3 dir, vec3 sunDir, float turbidity) {\n    float t = turbidity;\n\n    float cosTheta = max(dir.y, 0.0);\n    float thetaSun = acos(clamp(sunDir.y, -1.0, 1.0));\n    float cosGamma = clamp(dot(dir, sunDir), -1.0, 1.0);\n    float gamma = acos(cosGamma);\n\n    float ay =  0.1787 * t - 1.4630;\n    float by = -0.3554 * t + 0.4275;\n    float cy = -0.0227 * t + 5.3251;\n    float dy =  0.1206 * t - 2.5771;\n    float ey = -0.0670 * t + 0.3703;\n\n    float ax = -0.0193 * t - 0.2592;\n    float bx = -0.0665 * t + 0.0008;\n    float cx = -0.0004 * t + 0.2125;\n    float dx = -0.0641 * t - 0.8989;\n    float ex = -0.0033 * t + 0.0452;\n\n    float ayy = -0.0167 * t - 0.2608;\n    float byy = -0.0950 * t + 0.0092;\n    float cyy = -0.0079 * t + 0.2102;\n    float dyy = -0.0441 * t - 1.6537;\n    float eyy = -0.0109 * t + 0.0529;\n\n    // Zenith luminance, kcd/m^2.\n    //\n    // Preetham's zenith fit is a daytime fit and goes *negative* below about a 10\n    // degree sun elevation - a documented limitation of the model, pinned by\n    // PreethamSkyTest in core. Below that limit the value at the limit is carried\n    // down and faded exponentially, which keeps twilight ordered and positive.\n    // This must stay identical to PreethamSky.usableZenithLuminance.\n    const float VALIDITY_ELEVATION_LIMIT = 0.17453293;   // 10 degrees\n    const float TWILIGHT_FALLOFF = 17.2;\n    float elevation = SKY_PI * 0.5 - thetaSun;\n    float thetaLimit = SKY_PI * 0.5 - VALIDITY_ELEVATION_LIMIT;\n    float chiAt = (4.0 / 9.0 - t / 120.0) * (SKY_PI - 2.0 * min(thetaSun, thetaLimit));\n    float zenithY = (4.0453 * t - 4.9710) * tan(chiAt) - 0.2155 * t + 0.1208;\n    if (elevation < VALIDITY_ELEVATION_LIMIT) {\n        zenithY *= exp((elevation - VALIDITY_ELEVATION_LIMIT) * TWILIGHT_FALLOFF);\n    }\n\n    float ts = thetaSun;\n    float ts2 = ts * ts;\n    float ts3 = ts2 * ts;\n    float t2 = t * t;\n\n    float zenithX =\n        ( 0.00166 * ts3 - 0.00375 * ts2 + 0.00209 * ts) * t2 +\n        (-0.02903 * ts3 + 0.06377 * ts2 - 0.03202 * ts + 0.00394) * t +\n        ( 0.11693 * ts3 - 0.21196 * ts2 + 0.06052 * ts + 0.25886);\n\n    float zenithYc =\n        ( 0.00275 * ts3 - 0.00610 * ts2 + 0.00317 * ts) * t2 +\n        (-0.04214 * ts3 + 0.08970 * ts2 - 0.04153 * ts + 0.00516) * t +\n        ( 0.15346 * ts3 - 0.26756 * ts2 + 0.06670 * ts + 0.26688);\n\n    float fY  = perezF(cosTheta, gamma, ay, by, cy, dy, ey);\n    float fY0 = perezF(1.0, thetaSun, ay, by, cy, dy, ey);\n    float fx  = perezF(cosTheta, gamma, ax, bx, cx, dx, ex);\n    float fx0 = perezF(1.0, thetaSun, ax, bx, cx, dx, ex);\n    float fy  = perezF(cosTheta, gamma, ayy, byy, cyy, dyy, eyy);\n    float fy0 = perezF(1.0, thetaSun, ayy, byy, cyy, dyy, eyy);\n\n    float bigY = max(0.0, zenithY * fY / fY0);\n    float chromaX = zenithX * fx / fx0;\n    float chromaY = zenithYc * fy / fy0;\n\n    return max(vec3(0.0), xyYToLinearSrgb(chromaX, chromaY, bigY));\n}\n\n// Sun disc plus forward-scattered glow, added on top of the sky radiance.\nvec3 sunDisc(vec3 dir, vec3 sunDir, vec3 sunColour) {\n    float cosAngle = dot(dir, sunDir);\n    // The sun subtends about 0.53 degrees; a touch of softening keeps it from\n    // aliasing into a square when the camera turns.\n    float disc = smoothstep(0.99987, 0.99995, cosAngle);\n    float glow = pow(max(cosAngle, 0.0), 900.0) * 0.35;\n    return sunColour * (disc * 60.0 + glow);\n}\n\n// Below the horizon the Preetham model is undefined. Rather than let it go\n// negative, fade into a darkened version of the horizon band, which is what the\n// sea reflects when a wave face tips the reflection vector downward.\nvec3 skyRadiance(vec3 dir, vec3 sunDir, float turbidity) {\n    vec3 above = preethamSky(vec3(dir.x, max(dir.y, 0.0), dir.z), sunDir, turbidity);\n    if (dir.y >= 0.0) {\n        return above;\n    }\n    vec3 horizon = preethamSky(normalize(vec3(dir.x, 0.0001, dir.z)), sunDir, turbidity);\n    return mix(horizon, horizon * 0.25, clamp(-dir.y * 3.0, 0.0, 1.0));\n}\n\n\nin vec3 v_worldPosition;\nin vec3 v_normal;\nin float v_material;\nin float v_height;\n\nout vec4 fragColor;\n\nuniform vec3 u_cameraPosition;\nuniform vec3 u_sunDirection;\nuniform vec3 u_sunColour;\nuniform float u_turbidity;\n\nvoid main() {\n    vec3 n = normalize(v_normal);\n    vec3 v = normalize(u_cameraPosition - v_worldPosition);\n    // Two-sided: a sail is a membrane and is seen from both faces.\n    if (dot(n, v) < 0.0 && v_material > 2.5) {\n        n = -n;\n    }\n\n    vec3 albedo;\n    float roughness;\n    if (v_material < 0.5) {\n        // Topsides: white above the boot stripe, dark below it.\n        albedo = v_height < 0.06 ? vec3(0.06, 0.09, 0.11) : vec3(0.86, 0.88, 0.89);\n        roughness = 0.25;\n    } else if (v_material < 1.5) {\n        albedo = vec3(0.22, 0.24, 0.26);   // non-skid deck\n        roughness = 0.7;\n    } else if (v_material < 2.5) {\n        albedo = vec3(0.14, 0.15, 0.16);   // carbon spar\n        roughness = 0.35;\n    } else {\n        albedo = vec3(0.93, 0.93, 0.90);   // sailcloth\n        roughness = 0.85;\n    }\n\n    // Sky as the ambient term, sampled up and along the normal, so the boat picks\n    // up the same colour cast the sea does.\n    vec3 skyAbove = skyRadiance(vec3(0.0, 1.0, 0.0), u_sunDirection, u_turbidity);\n    vec3 skyAlong = skyRadiance(normalize(n + vec3(0.0, 0.35, 0.0)), u_sunDirection, u_turbidity);\n    vec3 ambient = mix(skyAbove, skyAlong, 0.6) * (0.35 + 0.35 * (n.y * 0.5 + 0.5));\n\n    float ndl = max(dot(n, u_sunDirection), 0.0);\n    vec3 direct = u_sunColour * ndl * 2.2;\n\n    // Sailcloth is thin: light behind it comes through, which is most of why a\n    // sail reads as fabric rather than as a painted board.\n    if (v_material > 2.5) {\n        float through = max(dot(-n, u_sunDirection), 0.0);\n        direct += u_sunColour * pow(through, 1.5) * 1.1;\n    }\n\n    vec3 h = normalize(v + u_sunDirection);\n    float gloss = pow(max(dot(n, h), 0.0), mix(120.0, 4.0, roughness));\n    vec3 specular = u_sunColour * gloss * (1.0 - roughness) * 1.5;\n\n    fragColor = vec4(albedo * (ambient + direct) + specular, 1.0);\n}\n",
  "boat.vert": "// Boat vertex stage.\n//\n// The hull is a static mesh in boat-local coordinates - bow along +X, port along\n// +Z, up along +Y - and the model matrix carries it onto the water: position from\n// the sailing model, heading, and the pitch and roll read off the wave surface.\n// Nothing here knows about waves; the boat's attitude was already resolved by the\n// physics, which is the same physics the server runs.\n\nin vec3 a_position;\nin vec3 a_normal;\nin float a_material;      // 0 hull, 1 deck, 2 rig, 3 sail\n\nuniform mat4 u_viewProjection;\nuniform mat4 u_model;\nuniform mat3 u_normalMatrix;\n\nout vec3 v_worldPosition;\nout vec3 v_normal;\nout float v_material;\nout float v_height;\n\nvoid main() {\n    vec4 world = u_model * vec4(a_position, 1.0);\n    v_worldPosition = world.xyz;\n    v_normal = normalize(u_normalMatrix * a_normal);\n    v_material = a_material;\n    // Height above the local waterline, used to darken the topsides where they\n    // are wet and to keep the bootstripe from floating.\n    v_height = a_position.y;\n    gl_Position = u_viewProjection * world;\n}\n",
  "fullscreen.vert": "// Pass-through for full-target passes: positions arrive already in clip space.\nin vec2 a_position;\nin vec2 a_texCoord0;\nout vec2 v_uv;\n\nvoid main() {\n    v_uv = a_texCoord0;\n    gl_Position = vec4(a_position, 0.0, 1.0);\n}\n",
  "ocean_assemble_derivatives.frag": "// Builds the shading map: surface slope, the folding Jacobian, and accumulated\n// foam.\n//\n// The Jacobian of the horizontal displacement map measures how much a patch of\n// water has been compressed. Below 1 the surface is folding; at or below 0 it has\n// turned inside out, which is physically a breaking crest. That is the honest\n// source of whitecaps - not a height threshold, which puts foam on the top of\n// every swell whether it is breaking or not.\n//\n//   J = (1 + L*dDx/dx)(1 + L*dDz/dz) - (L*dDx/dz)^2\n//\n// Foam is stored against the *undisplaced* grid coordinate, which is the\n// Lagrangian label of the water particle. A particle keeps its label as it orbits,\n// so foam written here rides with the water automatically when the surface is\n// displaced, with no advection pass at all.\n\nin vec2 v_uv;\nout vec4 fragColor;\n\nuniform sampler2D u_spatialA;      // Dx, Dz, h, dDx/dz\nuniform sampler2D u_spatialB;      // dh/dx, dh/dz, dDx/dx, dDz/dz\nuniform sampler2D u_previousFoam;  // previous frame's output of this pass\nuniform float u_choppiness;\nuniform float u_foamDecay;         // exp(-dt / tau)\nuniform float u_foamThreshold;     // Jacobian below which foam is injected\nuniform float u_foamInjection;     // gain * dt\n\nvoid main() {\n    ivec2 texel = ivec2(gl_FragCoord.xy);\n    vec4 a = texelFetch(u_spatialA, texel, 0);\n    vec4 b = texelFetch(u_spatialB, texel, 0);\n\n    float dhdx = b.r;\n    float dhdz = b.g;\n    float dDxdx = b.b;\n    float dDzdz = b.a;\n    float dDxdz = a.a;\n\n    float L = u_choppiness;\n    float jacobian = (1.0 + L * dDxdx) * (1.0 + L * dDzdz) - (L * dDxdz) * (L * dDxdz);\n\n    // Foam is a rate balance, not a per-frame addition:\n    //\n    //     d(foam)/dt = deposition - foam / tau\n    //\n    // so the deposited amount has to be scaled by the frame time. Without that the\n    // equilibrium coverage depends on the frame rate - a scene running at 30 fps\n    // accumulates thirty times the foam of one running at 1 fps, and a storm turns\n    // uniformly white while the same sea stepped coarsely stays glassy.\n    float previous = texelFetch(u_previousFoam, texel, 0).a;\n    float deposition = max(0.0, u_foamThreshold - jacobian) * u_foamInjection;\n    float foam = min(1.0, previous * u_foamDecay + deposition);\n\n    fragColor = vec4(dhdx, dhdz, jacobian, foam);\n}\n",
  "ocean_assemble_displacement.frag": "// Unpacks the transformed signal set 0 into a world-space displacement map.\n//\n// After the inverse transform the packed signal A + i*B has A in .r and B in .g\n// (and likewise .b / .a for the second pair), because both A and B were Hermitian\n// and therefore transform to real fields.\n\nin vec2 v_uv;\nout vec4 fragColor;\n\nuniform sampler2D u_spatialA;   // Dx, Dz, h, dDx/dz\nuniform float u_choppiness;\n\nvoid main() {\n    vec4 s = texelFetch(u_spatialA, ivec2(gl_FragCoord.xy), 0);\n    float dx = s.r * u_choppiness;\n    float dz = s.g * u_choppiness;\n    float height = s.b;\n    fragColor = vec4(dx, height, dz, 0.0);\n}\n",
  "ocean_evolve.frag": "// Advances the initial spectrum to time t and builds the four packed complex\n// signals the inverse FFT consumes.\n//\n// h~(k,t) = h0(k) e^{i w t} + conj(h0(-k)) e^{-i w t}\n//\n// Two Hermitian spectra are packed into one complex transform as A + i*B: the\n// inverse FFT then returns A in its real part and B in its imaginary part, which\n// halves the number of transforms. Every signal below is Hermitian, because\n// multiplying a Hermitian spectrum by i*k (odd in k, and i flips conjugation)\n// leaves it Hermitian.\n//\n//   pass 0 -> (Dx + i*Dz,        h + i*dDx/dz)\n//   pass 1 -> (dh/dx + i*dh/dz,  dDx/dx + i*dDz/dz)\n\n// Complex arithmetic on vec2 (x = real, y = imaginary).\n\nvec2 cmul(vec2 a, vec2 b) {\n    return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);\n}\n\n// Multiplication by i: rotates a quarter turn counter-clockwise.\nvec2 cmuli(vec2 a) {\n    return vec2(-a.y, a.x);\n}\n\n// Multiplication by -i.\nvec2 cmulnegi(vec2 a) {\n    return vec2(a.y, -a.x);\n}\n\nvec2 cconj(vec2 a) {\n    return vec2(a.x, -a.y);\n}\n\n\nin vec2 v_uv;\nout vec4 fragColor;\n\nuniform sampler2D u_h0;        // h0.re, h0.im, conj(h0(-k)).re, conj(h0(-k)).im\nuniform sampler2D u_waveData;  // kx, kz, |k|, omega\nuniform float u_time;\nuniform int u_outputSet;       // 0 or 1\n\nvoid main() {\n    ivec2 texel = ivec2(gl_FragCoord.xy);\n    vec4 h0 = texelFetch(u_h0, texel, 0);\n    vec4 wave = texelFetch(u_waveData, texel, 0);\n\n    float kx = wave.x;\n    float kz = wave.y;\n    float k = wave.z;\n    float omega = wave.w;\n\n    float phase = omega * u_time;\n    vec2 rot = vec2(cos(phase), sin(phase));\n\n    // h0 * e^{i w t} + conj(h0(-k)) * e^{-i w t}\n    vec2 hTilde = cmul(h0.xy, rot) + cmul(h0.zw, vec2(rot.x, -rot.y));\n\n    if (k < 1e-8) {\n        fragColor = vec4(0.0);\n        return;\n    }\n\n    float invK = 1.0 / k;\n    float nx = kx * invK;\n    float nz = kz * invK;\n\n    if (u_outputSet == 0) {\n        // Horizontal displacement: D = -i * (k/|k|) * h~\n        vec2 dx = cmulnegi(hTilde) * nx;\n        vec2 dz = cmulnegi(hTilde) * nz;\n        // dDx/dz = i*kz * Dx = (kx*kz/|k|) * h~\n        vec2 jxz = hTilde * (kx * kz * invK);\n        fragColor = vec4(dx + cmuli(dz), hTilde + cmuli(jxz));\n    } else {\n        // Surface slopes: dh/dx = i*kx*h~, dh/dz = i*kz*h~\n        vec2 dhdx = cmuli(hTilde) * kx;\n        vec2 dhdz = cmuli(hTilde) * kz;\n        // Displacement gradients: dDx/dx = (kx^2/|k|) h~, dDz/dz = (kz^2/|k|) h~\n        vec2 ddxdx = hTilde * (kx * kx * invK);\n        vec2 ddzdz = hTilde * (kz * kz * invK);\n        fragColor = vec4(dhdx + cmuli(dhdz), ddxdx + cmuli(ddzdz));\n    }\n}\n",
  "ocean_fft.frag": "// One butterfly stage of a Cooley-Tukey inverse FFT, applied to two independent\n// complex signals packed in .rg and .ba.\n//\n// The schedule comes from a precomputed table generated by ButterflyPlan on the\n// CPU: texel (stage, lane) holds (twiddle.re, twiddle.im, indexA, indexB). Every\n// lane performs the same unbranched operation, out = a + w*b, because a lane in\n// the subtracting wing of a butterfly carries a twiddle that is already half a\n// turn further round the unit circle. Stage 0's indices are bit-reversed, which\n// folds the reordering into the first pass.\n\n// Complex arithmetic on vec2 (x = real, y = imaginary).\n\nvec2 cmul(vec2 a, vec2 b) {\n    return vec2(a.x * b.x - a.y * b.y, a.x * b.y + a.y * b.x);\n}\n\n// Multiplication by i: rotates a quarter turn counter-clockwise.\nvec2 cmuli(vec2 a) {\n    return vec2(-a.y, a.x);\n}\n\n// Multiplication by -i.\nvec2 cmulnegi(vec2 a) {\n    return vec2(a.y, -a.x);\n}\n\nvec2 cconj(vec2 a) {\n    return vec2(a.x, -a.y);\n}\n\n\nin vec2 v_uv;\nout vec4 fragColor;\n\nuniform sampler2D u_source;\nuniform sampler2D u_butterfly;   // log2(N) wide, N tall\nuniform int u_stage;\nuniform int u_horizontal;        // 1 for the row pass, 0 for the column pass\n\nvoid main() {\n    ivec2 texel = ivec2(gl_FragCoord.xy);\n    int lane = u_horizontal == 1 ? texel.x : texel.y;\n\n    vec4 plan = texelFetch(u_butterfly, ivec2(u_stage, lane), 0);\n    vec2 twiddle = plan.xy;\n    int indexA = int(plan.z);\n    int indexB = int(plan.w);\n\n    ivec2 coordA = u_horizontal == 1 ? ivec2(indexA, texel.y) : ivec2(texel.x, indexA);\n    ivec2 coordB = u_horizontal == 1 ? ivec2(indexB, texel.y) : ivec2(texel.x, indexB);\n\n    vec4 a = texelFetch(u_source, coordA, 0);\n    vec4 b = texelFetch(u_source, coordB, 0);\n\n    fragColor = vec4(a.rg + cmul(twiddle, b.rg),\n                     a.ba + cmul(twiddle, b.ba));\n}\n",
  "ocean_surface.frag": "// Ocean surface shading.\n//\n// The order matters and it is not arbitrary. Water is almost entirely a\n// reflector at grazing angles and almost entirely a scatterer when you look\n// straight down into it, so Fresnel is not a finishing touch here, it is the\n// structure of the whole shader: reflection and scattering are computed\n// separately and mixed by it.\n//\n//  1. Slopes are summed across cascades, with the fine ones faded by distance so\n//     they cannot alias.\n//  2. The normal accounts for horizontal compression, not just the height slope.\n//     On a choppy sea the two differ sharply on the steep face of a crest, which\n//     is exactly where the eye is looking.\n//  3. Reflection is the analytic sky evaluated in the reflected direction. That\n//     beats a cubemap: no resolution limit on the sun's reflection, no seams, and\n//     it stays correct as the sun moves.\n//  4. Subsurface scattering lights the wave from behind. This is the single most\n//     valuable term in the shader - it is what turns grey geometry into water.\n//  5. Foam from the Jacobian, broken up by Worley noise.\n\n// Shared between the ocean vertex and fragment stages. Kept in one file so the\n// two stages cannot drift apart on how the cascades are laid out.\n\nconst float WATER_F0 = 0.0204;   // Schlick F0 for an IOR of 1.333\n\n// Analytic daylight sky, after Preetham, Shirley and Smits (1999).\n//\n// The design brief asks for Hosek-Wilkie with Preetham as the fallback. Preetham\n// is what is implemented, deliberately: Hosek-Wilkie's radiance is driven by a\n// large fitted dataset published by its authors, and that dataset has to be\n// imported from them rather than reproduced from memory. Preetham's coefficients\n// are a small closed-form table in the paper, so they can be written down, read\n// back, and checked. PreethamSkyTest in core verifies this model's behaviour\n// against physical expectations.\n//\n//   F(theta, gamma) = (1 + A e^{B/cos theta}) (1 + C e^{D gamma} + E cos^2 gamma)\n//\n// evaluated for luminance Y and for the chromaticity coordinates x and y, each\n// normalised against the value at the zenith.\n\nconst float SKY_PI = 3.14159265359;\n\nfloat perezF(float cosTheta, float gamma, float a, float b, float c, float d, float e) {\n    float cosGamma = cos(gamma);\n    return (1.0 + a * exp(b / max(cosTheta, 0.01)))\n         * (1.0 + c * exp(d * gamma) + e * cosGamma * cosGamma);\n}\n\nvec3 xyYToLinearSrgb(float x, float y, float bigY) {\n    float safeY = max(y, 1e-4);\n    vec3 xyz = vec3(x * bigY / safeY, bigY, (1.0 - x - y) * bigY / safeY);\n    // XYZ -> linear sRGB (sRGB primaries, D65). Column-major, as GLSL expects.\n    mat3 m = mat3(\n        3.2404542, -0.9692660,  0.0556434,\n       -1.5371385,  1.8760108, -0.2040259,\n       -0.4985314,  0.0415560,  1.0572252);\n    return m * xyz;\n}\n\n// dir and sunDir must be unit vectors with +y up. Returns linear RGB radiance in\n// kcd/m^2; a clear zenith at a 30 degree sun elevation lands around 2.\nvec3 preethamSky(vec3 dir, vec3 sunDir, float turbidity) {\n    float t = turbidity;\n\n    float cosTheta = max(dir.y, 0.0);\n    float thetaSun = acos(clamp(sunDir.y, -1.0, 1.0));\n    float cosGamma = clamp(dot(dir, sunDir), -1.0, 1.0);\n    float gamma = acos(cosGamma);\n\n    float ay =  0.1787 * t - 1.4630;\n    float by = -0.3554 * t + 0.4275;\n    float cy = -0.0227 * t + 5.3251;\n    float dy =  0.1206 * t - 2.5771;\n    float ey = -0.0670 * t + 0.3703;\n\n    float ax = -0.0193 * t - 0.2592;\n    float bx = -0.0665 * t + 0.0008;\n    float cx = -0.0004 * t + 0.2125;\n    float dx = -0.0641 * t - 0.8989;\n    float ex = -0.0033 * t + 0.0452;\n\n    float ayy = -0.0167 * t - 0.2608;\n    float byy = -0.0950 * t + 0.0092;\n    float cyy = -0.0079 * t + 0.2102;\n    float dyy = -0.0441 * t - 1.6537;\n    float eyy = -0.0109 * t + 0.0529;\n\n    // Zenith luminance, kcd/m^2.\n    //\n    // Preetham's zenith fit is a daytime fit and goes *negative* below about a 10\n    // degree sun elevation - a documented limitation of the model, pinned by\n    // PreethamSkyTest in core. Below that limit the value at the limit is carried\n    // down and faded exponentially, which keeps twilight ordered and positive.\n    // This must stay identical to PreethamSky.usableZenithLuminance.\n    const float VALIDITY_ELEVATION_LIMIT = 0.17453293;   // 10 degrees\n    const float TWILIGHT_FALLOFF = 17.2;\n    float elevation = SKY_PI * 0.5 - thetaSun;\n    float thetaLimit = SKY_PI * 0.5 - VALIDITY_ELEVATION_LIMIT;\n    float chiAt = (4.0 / 9.0 - t / 120.0) * (SKY_PI - 2.0 * min(thetaSun, thetaLimit));\n    float zenithY = (4.0453 * t - 4.9710) * tan(chiAt) - 0.2155 * t + 0.1208;\n    if (elevation < VALIDITY_ELEVATION_LIMIT) {\n        zenithY *= exp((elevation - VALIDITY_ELEVATION_LIMIT) * TWILIGHT_FALLOFF);\n    }\n\n    float ts = thetaSun;\n    float ts2 = ts * ts;\n    float ts3 = ts2 * ts;\n    float t2 = t * t;\n\n    float zenithX =\n        ( 0.00166 * ts3 - 0.00375 * ts2 + 0.00209 * ts) * t2 +\n        (-0.02903 * ts3 + 0.06377 * ts2 - 0.03202 * ts + 0.00394) * t +\n        ( 0.11693 * ts3 - 0.21196 * ts2 + 0.06052 * ts + 0.25886);\n\n    float zenithYc =\n        ( 0.00275 * ts3 - 0.00610 * ts2 + 0.00317 * ts) * t2 +\n        (-0.04214 * ts3 + 0.08970 * ts2 - 0.04153 * ts + 0.00516) * t +\n        ( 0.15346 * ts3 - 0.26756 * ts2 + 0.06670 * ts + 0.26688);\n\n    float fY  = perezF(cosTheta, gamma, ay, by, cy, dy, ey);\n    float fY0 = perezF(1.0, thetaSun, ay, by, cy, dy, ey);\n    float fx  = perezF(cosTheta, gamma, ax, bx, cx, dx, ex);\n    float fx0 = perezF(1.0, thetaSun, ax, bx, cx, dx, ex);\n    float fy  = perezF(cosTheta, gamma, ayy, byy, cyy, dyy, eyy);\n    float fy0 = perezF(1.0, thetaSun, ayy, byy, cyy, dyy, eyy);\n\n    float bigY = max(0.0, zenithY * fY / fY0);\n    float chromaX = zenithX * fx / fx0;\n    float chromaY = zenithYc * fy / fy0;\n\n    return max(vec3(0.0), xyYToLinearSrgb(chromaX, chromaY, bigY));\n}\n\n// Sun disc plus forward-scattered glow, added on top of the sky radiance.\nvec3 sunDisc(vec3 dir, vec3 sunDir, vec3 sunColour) {\n    float cosAngle = dot(dir, sunDir);\n    // The sun subtends about 0.53 degrees; a touch of softening keeps it from\n    // aliasing into a square when the camera turns.\n    float disc = smoothstep(0.99987, 0.99995, cosAngle);\n    float glow = pow(max(cosAngle, 0.0), 900.0) * 0.35;\n    return sunColour * (disc * 60.0 + glow);\n}\n\n// Below the horizon the Preetham model is undefined. Rather than let it go\n// negative, fade into a darkened version of the horizon band, which is what the\n// sea reflects when a wave face tips the reflection vector downward.\nvec3 skyRadiance(vec3 dir, vec3 sunDir, float turbidity) {\n    vec3 above = preethamSky(vec3(dir.x, max(dir.y, 0.0), dir.z), sunDir, turbidity);\n    if (dir.y >= 0.0) {\n        return above;\n    }\n    vec3 horizon = preethamSky(normalize(vec3(dir.x, 0.0001, dir.z)), sunDir, turbidity);\n    return mix(horizon, horizon * 0.25, clamp(-dir.y * 3.0, 0.0, 1.0));\n}\n\n// Worley (cellular) noise, used to break foam into cells instead of leaving it a\n// flat white wash. Real foam is a raft of bubbles with visible structure, and a\n// uniform white crest is one of the two or three things that most reliably makes\n// rendered water look fake.\n\nvec2 worleyHash(vec2 cell) {\n    vec2 p = vec2(dot(cell, vec2(127.1, 311.7)), dot(cell, vec2(269.5, 183.3)));\n    return fract(sin(p) * 43758.5453);\n}\n\n// Returns the distance to the nearest feature point, roughly in [0, 1].\nfloat worley(vec2 position) {\n    vec2 cell = floor(position);\n    vec2 local = fract(position);\n    float best = 8.0;\n    for (int y = -1; y <= 1; y++) {\n        for (int x = -1; x <= 1; x++) {\n            vec2 offset = vec2(float(x), float(y));\n            vec2 feature = offset + worleyHash(cell + offset) - local;\n            best = min(best, dot(feature, feature));\n        }\n    }\n    return sqrt(best);\n}\n\n// Two octaves: large rafts with finer bubble structure inside them.\nfloat foamPattern(vec2 position) {\n    float a = 1.0 - worley(position);\n    float b = 1.0 - worley(position * 2.7 + 13.7);\n    return clamp(a * 0.65 + b * 0.35, 0.0, 1.0);\n}\n\n\nin vec3 v_worldPosition;\nin vec3 v_undisplacedPosition;\nin float v_viewDistance;\n\nout vec4 fragColor;\n\nuniform vec3 u_cameraPosition;\nuniform vec3 u_sunDirection;\nuniform vec3 u_sunColour;\nuniform float u_turbidity;\n\nuniform sampler2D u_derivatives0;\nuniform sampler2D u_derivatives1;\nuniform sampler2D u_derivatives2;\nuniform vec3 u_patchSizes;\nuniform int u_cascadeCount;\nuniform float u_choppiness;\n\nuniform vec3 u_scatterColour;      // colour of light that has been through the water\nuniform vec3 u_deepColour;         // colour of water with nothing under it\nuniform float u_waterDepth;        // metres, for Beer-Lambert attenuation\nuniform vec3 u_extinction;         // per-metre attenuation, RGB\nuniform float u_foamScale;\nuniform float u_normalDetailFade;\n\n// Smith-GGX specular for the sun, the only punctual light in the scene.\nfloat ggxSpecular(vec3 n, vec3 v, vec3 l, float roughness) {\n    vec3 h = normalize(v + l);\n    float a = roughness * roughness;\n    float a2 = a * a;\n    float nh = max(dot(n, h), 0.0);\n    float nv = max(dot(n, v), 1e-4);\n    float nl = max(dot(n, l), 0.0);\n\n    float d = nh * nh * (a2 - 1.0) + 1.0;\n    float distribution = a2 / (SKY_PI * d * d);\n\n    float k = a * 0.5;\n    float gv = nv / (nv * (1.0 - k) + k);\n    float gl = nl / (nl * (1.0 - k) + k);\n\n    return distribution * gv * gl / (4.0 * nv * max(nl, 1e-4)) * nl;\n}\n\nvoid main() {\n    vec3 viewVector = u_cameraPosition - v_worldPosition;\n    vec3 v = normalize(viewVector);\n\n    // Fine cascades carry detail that falls below a pixel with distance. Letting\n    // it through produces a crawling glitter that reads as noise, so each cascade\n    // fades once its wavelength approaches the projected pixel size.\n    vec2 slope = vec2(0.0);\n    float jacobian = 1.0;\n    float foam = 0.0;\n\n    vec4 d0 = texture(u_derivatives0, v_undisplacedPosition.xz / u_patchSizes.x);\n    slope += d0.xy;\n    jacobian = min(jacobian, d0.z);\n    foam = max(foam, d0.w);\n\n    if (u_cascadeCount > 1) {\n        float w = 1.0 - smoothstep(u_patchSizes.y * u_normalDetailFade,\n                                   u_patchSizes.y * u_normalDetailFade * 4.0, v_viewDistance);\n        vec4 d1 = texture(u_derivatives1, v_undisplacedPosition.xz / u_patchSizes.y);\n        slope += d1.xy * w;\n        jacobian = min(jacobian, mix(1.0, d1.z, w));\n        foam = max(foam, d1.w * w);\n    }\n    if (u_cascadeCount > 2) {\n        float w = 1.0 - smoothstep(u_patchSizes.z * u_normalDetailFade,\n                                   u_patchSizes.z * u_normalDetailFade * 4.0, v_viewDistance);\n        vec4 d2 = texture(u_derivatives2, v_undisplacedPosition.xz / u_patchSizes.z);\n        slope += d2.xy * w;\n        jacobian = min(jacobian, mix(1.0, d2.z, w));\n        foam = max(foam, d2.w * w);\n    }\n\n    // Horizontal compression steepens the apparent slope: a patch squeezed to\n    // half its width doubles the gradient across it.\n    float compression = max(0.25, jacobian);\n    vec3 n = normalize(vec3(-slope.x / compression, 1.0, -slope.y / compression));\n\n    float nv = max(dot(n, v), 0.0);\n    float fresnel = WATER_F0 + (1.0 - WATER_F0) * pow(1.0 - nv, 5.0);\n\n    // --- Reflection -------------------------------------------------------\n    vec3 reflectDir = reflect(-v, n);\n    vec3 reflection = skyRadiance(reflectDir, u_sunDirection, u_turbidity);\n\n    // A rough sea reflects a blurred sky. Approximated by blending toward the\n    // radiance straight up, which is the mean of the hemisphere to first order.\n    float roughness = clamp(0.02 + 0.28 * length(slope), 0.02, 0.4);\n    vec3 averageSky = skyRadiance(vec3(0.0, 1.0, 0.0), u_sunDirection, u_turbidity);\n    reflection = mix(reflection, averageSky, roughness * 0.8);\n\n    // The GGX lobe is already normalised, so this is a plain intensity for the\n    // solar disc. Pushed harder the sun track stops being glitter on facets and\n    // becomes a row of blown white discs.\n    reflection += u_sunColour * ggxSpecular(n, v, u_sunDirection, roughness) * 1.6;\n\n    // --- Transmission and subsurface scattering ---------------------------\n    // Height above the mean surface drives the scattering: a crest is a thin\n    // wedge of water with the sun behind it, a trough is deep and dark.\n    float heightAboveMean = max(0.0, v_worldPosition.y);\n\n    // Light bending through the crest toward the eye.\n    float backLight = pow(max(0.0, dot(v, -u_sunDirection)), 4.0);\n    // Strongest when the wave face is tilted away from the sun.\n    float facing = pow(max(0.0, 0.5 - 0.5 * dot(u_sunDirection, n)), 3.0);\n    float scatter = heightAboveMean * backLight * facing * 1.8;\n    // A weaker, view-independent term so troughs are not pure black.\n    scatter += 0.35 * max(0.0, dot(n, v));\n\n    vec3 transmitted = u_scatterColour * scatter * u_sunColour;\n\n    // Beer-Lambert through the water column to whatever is beneath. In the open\n    // ocean this saturates to the deep colour within a few metres, which is why\n    // deep water is blue regardless of the bottom.\n    vec3 attenuation = exp(-u_extinction * u_waterDepth);\n    transmitted += mix(u_deepColour, u_deepColour * 1.6, attenuation.b) * 0.25\n                 * max(0.15, u_sunColour.g);\n\n    vec3 colour = mix(transmitted, reflection, fresnel);\n\n    // --- Foam -------------------------------------------------------------\n    if (foam > 0.001) {\n        float pattern = foamPattern(v_undisplacedPosition.xz * u_foamScale);\n        float coverage = clamp(foam * 1.4, 0.0, 1.0);\n        // Foam appears where the accumulated value exceeds the local threshold of\n        // the noise field, so rafts grow and shrink instead of fading uniformly.\n        float mask = smoothstep(1.0 - coverage - 0.15, 1.0 - coverage + 0.15, pattern);\n        vec3 foamLit = vec3(0.85) * (max(0.25, dot(n, u_sunDirection)) * u_sunColour\n                                     + averageSky * 0.35);\n        colour = mix(colour, foamLit, mask * coverage);\n    }\n\n    fragColor = vec4(colour, 1.0);\n}\n",
  "ocean_surface.vert": "// Screen-space projected grid.\n//\n// The mesh is a plain lattice in [0,1]^2 that never changes. Each vertex is\n// mapped to an NDC point inside the band of screen the CPU found water in, then\n// un-projected and intersected with the water plane. Vertices therefore land\n// evenly across the screen rather than across the world: dense in the\n// foreground, sparse at the horizon, with no LOD rings and so no seams to stitch.\n//\n// Rays that miss the plane - anything at or above the horizon - are planted at a\n// fixed distance instead of running to infinity, so the mesh closes cleanly at\n// the skyline rather than folding through the camera.\n//\n// Displacement is summed over the cascades, each tiling at its own patch size.\n\n// Shared between the ocean vertex and fragment stages. Kept in one file so the\n// two stages cannot drift apart on how the cascades are laid out.\n\nconst float WATER_F0 = 0.0204;   // Schlick F0 for an IOR of 1.333\n\n\nin vec2 a_position;   // lattice coordinate in [0,1]^2\n\nuniform mat4 u_viewProjection;\nuniform mat4 u_inverseViewProjection;\nuniform vec2 u_ndcMin;\nuniform vec2 u_ndcMax;\nuniform vec3 u_cameraPosition;\nuniform float u_horizonDistance;\n\nuniform sampler2D u_displacement0;\nuniform sampler2D u_displacement1;\nuniform sampler2D u_displacement2;\nuniform vec3 u_patchSizes;\nuniform int u_cascadeCount;\nuniform float u_displacementFadeStart;\nuniform float u_displacementFadeEnd;\n\nout vec3 v_worldPosition;\nout vec3 v_undisplacedPosition;\nout float v_viewDistance;\n\nvoid main() {\n    vec2 ndc = mix(u_ndcMin, u_ndcMax, a_position);\n\n    vec4 nearHomogeneous = u_inverseViewProjection * vec4(ndc, -1.0, 1.0);\n    vec4 farHomogeneous = u_inverseViewProjection * vec4(ndc, 1.0, 1.0);\n    vec3 nearPoint = nearHomogeneous.xyz / nearHomogeneous.w;\n    vec3 direction = farHomogeneous.xyz / farHomogeneous.w - nearPoint;\n\n    // Intersect with the mean water plane. A ray parallel to it, or one heading\n    // away from it, is clamped to the horizon distance.\n    float denominator = direction.y;\n    float t = abs(denominator) < 1e-6 ? 1.0e9 : (-nearPoint.y / denominator);\n    if (t < 0.0) {\n        t = 1.0e9;\n    }\n    vec3 base = nearPoint + direction * t;\n\n    // Cap the reach so the far edge of the mesh is a definite distance rather\n    // than a numerically unstable point at infinity.\n    vec3 offset = base - u_cameraPosition;\n    float horizontal = length(offset.xz);\n    if (horizontal > u_horizonDistance) {\n        offset.xz *= u_horizonDistance / horizontal;\n        base = vec3(u_cameraPosition.x + offset.x, 0.0, u_cameraPosition.z + offset.z);\n    }\n    base.y = 0.0;\n\n    float distanceToCamera = length(base - u_cameraPosition);\n\n    // Beyond a few kilometres the displacement is far below a pixel and sampling\n    // it only produces shimmer, so it is faded out. The surface goes flat at the\n    // horizon, which is what the horizon looks like anyway.\n    float fade = 1.0 - smoothstep(u_displacementFadeStart, u_displacementFadeEnd,\n                                  distanceToCamera);\n\n    vec3 displacement = vec3(0.0);\n    if (fade > 0.0) {\n        displacement += texture(u_displacement0, base.xz / u_patchSizes.x).xyz;\n        if (u_cascadeCount > 1) {\n            displacement += texture(u_displacement1, base.xz / u_patchSizes.y).xyz;\n        }\n        if (u_cascadeCount > 2) {\n            displacement += texture(u_displacement2, base.xz / u_patchSizes.z).xyz;\n        }\n        displacement *= fade;\n    }\n\n    vec3 world = base + displacement;\n\n    v_undisplacedPosition = base;\n    v_worldPosition = world;\n    v_viewDistance = length(world - u_cameraPosition);\n    gl_Position = u_viewProjection * vec4(world, 1.0);\n}\n",
  "post_tonemap.frag": "// HDR resolve: exposure, ACES, then the sRGB transfer function.\n//\n// Written manually rather than relying on an sRGB framebuffer, because sRGB\n// default framebuffers are inconsistently supported across Android drivers and a\n// silently linear output looks washed out in a way that is easy to misdiagnose as\n// a lighting bug.\n\n// ACES filmic tone mapping, Narkowicz's curve fit.\n//\n// Chosen over Reinhard because a sea surface is mostly specular highlight against\n// a bright sky: Reinhard desaturates the sun glitter to grey, while the ACES\n// shoulder keeps the roll-off coloured, which is what makes water read as wet\n// rather than as metal.\nvec3 acesTonemap(vec3 colour) {\n    const float a = 2.51;\n    const float b = 0.03;\n    const float c = 2.43;\n    const float d = 0.59;\n    const float e = 0.14;\n    return clamp((colour * (a * colour + b)) / (colour * (c * colour + d) + e), 0.0, 1.0);\n}\n\nvec3 linearToSrgb(vec3 c) {\n    vec3 lo = c * 12.92;\n    vec3 hi = 1.055 * pow(max(c, vec3(1e-5)), vec3(1.0 / 2.4)) - 0.055;\n    return mix(lo, hi, step(vec3(0.0031308), c));\n}\n\n\nin vec2 v_uv;\nout vec4 fragColor;\n\nuniform sampler2D u_hdr;\nuniform sampler2D u_bloom;\nuniform float u_exposure;\nuniform float u_bloomStrength;\nuniform float u_vignette;\n\nvoid main() {\n    // The bloom chain has already been exposed; the scene has not.\n    vec3 hdr = texture(u_hdr, v_uv).rgb * u_exposure;\n    hdr += texture(u_bloom, v_uv).rgb * u_bloomStrength;\n\n    vec3 mapped = acesTonemap(hdr);\n\n    // Very slight corner darkening: the sea is brightest in the centre of frame\n    // where the sun track is, and a touch of vignette keeps the eye there.\n    vec2 centred = v_uv * 2.0 - 1.0;\n    float vignette = 1.0 - u_vignette * dot(centred, centred) * 0.25;\n    mapped *= vignette;\n\n    fragColor = vec4(linearToSrgb(mapped), 1.0);\n}\n",
  "sky.frag": "// Analytic daylight sky, after Preetham, Shirley and Smits (1999).\n//\n// The design brief asks for Hosek-Wilkie with Preetham as the fallback. Preetham\n// is what is implemented, deliberately: Hosek-Wilkie's radiance is driven by a\n// large fitted dataset published by its authors, and that dataset has to be\n// imported from them rather than reproduced from memory. Preetham's coefficients\n// are a small closed-form table in the paper, so they can be written down, read\n// back, and checked. PreethamSkyTest in core verifies this model's behaviour\n// against physical expectations.\n//\n//   F(theta, gamma) = (1 + A e^{B/cos theta}) (1 + C e^{D gamma} + E cos^2 gamma)\n//\n// evaluated for luminance Y and for the chromaticity coordinates x and y, each\n// normalised against the value at the zenith.\n\nconst float SKY_PI = 3.14159265359;\n\nfloat perezF(float cosTheta, float gamma, float a, float b, float c, float d, float e) {\n    float cosGamma = cos(gamma);\n    return (1.0 + a * exp(b / max(cosTheta, 0.01)))\n         * (1.0 + c * exp(d * gamma) + e * cosGamma * cosGamma);\n}\n\nvec3 xyYToLinearSrgb(float x, float y, float bigY) {\n    float safeY = max(y, 1e-4);\n    vec3 xyz = vec3(x * bigY / safeY, bigY, (1.0 - x - y) * bigY / safeY);\n    // XYZ -> linear sRGB (sRGB primaries, D65). Column-major, as GLSL expects.\n    mat3 m = mat3(\n        3.2404542, -0.9692660,  0.0556434,\n       -1.5371385,  1.8760108, -0.2040259,\n       -0.4985314,  0.0415560,  1.0572252);\n    return m * xyz;\n}\n\n// dir and sunDir must be unit vectors with +y up. Returns linear RGB radiance in\n// kcd/m^2; a clear zenith at a 30 degree sun elevation lands around 2.\nvec3 preethamSky(vec3 dir, vec3 sunDir, float turbidity) {\n    float t = turbidity;\n\n    float cosTheta = max(dir.y, 0.0);\n    float thetaSun = acos(clamp(sunDir.y, -1.0, 1.0));\n    float cosGamma = clamp(dot(dir, sunDir), -1.0, 1.0);\n    float gamma = acos(cosGamma);\n\n    float ay =  0.1787 * t - 1.4630;\n    float by = -0.3554 * t + 0.4275;\n    float cy = -0.0227 * t + 5.3251;\n    float dy =  0.1206 * t - 2.5771;\n    float ey = -0.0670 * t + 0.3703;\n\n    float ax = -0.0193 * t - 0.2592;\n    float bx = -0.0665 * t + 0.0008;\n    float cx = -0.0004 * t + 0.2125;\n    float dx = -0.0641 * t - 0.8989;\n    float ex = -0.0033 * t + 0.0452;\n\n    float ayy = -0.0167 * t - 0.2608;\n    float byy = -0.0950 * t + 0.0092;\n    float cyy = -0.0079 * t + 0.2102;\n    float dyy = -0.0441 * t - 1.6537;\n    float eyy = -0.0109 * t + 0.0529;\n\n    // Zenith luminance, kcd/m^2.\n    //\n    // Preetham's zenith fit is a daytime fit and goes *negative* below about a 10\n    // degree sun elevation - a documented limitation of the model, pinned by\n    // PreethamSkyTest in core. Below that limit the value at the limit is carried\n    // down and faded exponentially, which keeps twilight ordered and positive.\n    // This must stay identical to PreethamSky.usableZenithLuminance.\n    const float VALIDITY_ELEVATION_LIMIT = 0.17453293;   // 10 degrees\n    const float TWILIGHT_FALLOFF = 17.2;\n    float elevation = SKY_PI * 0.5 - thetaSun;\n    float thetaLimit = SKY_PI * 0.5 - VALIDITY_ELEVATION_LIMIT;\n    float chiAt = (4.0 / 9.0 - t / 120.0) * (SKY_PI - 2.0 * min(thetaSun, thetaLimit));\n    float zenithY = (4.0453 * t - 4.9710) * tan(chiAt) - 0.2155 * t + 0.1208;\n    if (elevation < VALIDITY_ELEVATION_LIMIT) {\n        zenithY *= exp((elevation - VALIDITY_ELEVATION_LIMIT) * TWILIGHT_FALLOFF);\n    }\n\n    float ts = thetaSun;\n    float ts2 = ts * ts;\n    float ts3 = ts2 * ts;\n    float t2 = t * t;\n\n    float zenithX =\n        ( 0.00166 * ts3 - 0.00375 * ts2 + 0.00209 * ts) * t2 +\n        (-0.02903 * ts3 + 0.06377 * ts2 - 0.03202 * ts + 0.00394) * t +\n        ( 0.11693 * ts3 - 0.21196 * ts2 + 0.06052 * ts + 0.25886);\n\n    float zenithYc =\n        ( 0.00275 * ts3 - 0.00610 * ts2 + 0.00317 * ts) * t2 +\n        (-0.04214 * ts3 + 0.08970 * ts2 - 0.04153 * ts + 0.00516) * t +\n        ( 0.15346 * ts3 - 0.26756 * ts2 + 0.06670 * ts + 0.26688);\n\n    float fY  = perezF(cosTheta, gamma, ay, by, cy, dy, ey);\n    float fY0 = perezF(1.0, thetaSun, ay, by, cy, dy, ey);\n    float fx  = perezF(cosTheta, gamma, ax, bx, cx, dx, ex);\n    float fx0 = perezF(1.0, thetaSun, ax, bx, cx, dx, ex);\n    float fy  = perezF(cosTheta, gamma, ayy, byy, cyy, dyy, eyy);\n    float fy0 = perezF(1.0, thetaSun, ayy, byy, cyy, dyy, eyy);\n\n    float bigY = max(0.0, zenithY * fY / fY0);\n    float chromaX = zenithX * fx / fx0;\n    float chromaY = zenithYc * fy / fy0;\n\n    return max(vec3(0.0), xyYToLinearSrgb(chromaX, chromaY, bigY));\n}\n\n// Sun disc plus forward-scattered glow, added on top of the sky radiance.\nvec3 sunDisc(vec3 dir, vec3 sunDir, vec3 sunColour) {\n    float cosAngle = dot(dir, sunDir);\n    // The sun subtends about 0.53 degrees; a touch of softening keeps it from\n    // aliasing into a square when the camera turns.\n    float disc = smoothstep(0.99987, 0.99995, cosAngle);\n    float glow = pow(max(cosAngle, 0.0), 900.0) * 0.35;\n    return sunColour * (disc * 60.0 + glow);\n}\n\n// Below the horizon the Preetham model is undefined. Rather than let it go\n// negative, fade into a darkened version of the horizon band, which is what the\n// sea reflects when a wave face tips the reflection vector downward.\nvec3 skyRadiance(vec3 dir, vec3 sunDir, float turbidity) {\n    vec3 above = preethamSky(vec3(dir.x, max(dir.y, 0.0), dir.z), sunDir, turbidity);\n    if (dir.y >= 0.0) {\n        return above;\n    }\n    vec3 horizon = preethamSky(normalize(vec3(dir.x, 0.0001, dir.z)), sunDir, turbidity);\n    return mix(horizon, horizon * 0.25, clamp(-dir.y * 3.0, 0.0, 1.0));\n}\n\n\nin vec3 v_viewRay;\nout vec4 fragColor;\n\nuniform vec3 u_sunDirection;\nuniform vec3 u_sunColour;\nuniform float u_turbidity;\n\nvoid main() {\n    vec3 dir = normalize(v_viewRay);\n    vec3 colour = skyRadiance(dir, u_sunDirection, u_turbidity);\n    colour += sunDisc(dir, u_sunDirection, u_sunColour);\n    fragColor = vec4(colour, 1.0);\n}\n",
  "sky.vert": "// Fullscreen sky pass: reconstructs a world-space view ray per pixel from the\n// inverse view-projection, so no sky geometry is needed at all.\nin vec2 a_position;\nin vec2 a_texCoord0;\n\nuniform mat4 u_inverseViewProjection;\n\nout vec3 v_viewRay;\n\nvoid main() {\n    vec4 near = u_inverseViewProjection * vec4(a_position, -1.0, 1.0);\n    vec4 far = u_inverseViewProjection * vec4(a_position, 1.0, 1.0);\n    v_viewRay = far.xyz / far.w - near.xyz / near.w;\n    gl_Position = vec4(a_position, 1.0, 1.0);\n}\n"
};
